/* Authors: Tom; Brendon (integrator) added PitchDetector_SamplesSinceEstimate (30 Oct 2026, with an AI coding assistant). */
/*
 * Pitch detector for the Autotune effect: tells how high the voice is (its
 * fundamental frequency: how many times a second the wave shape repeats)
 * and how sure it is (the confidence). Input: 48 kHz mono 16-bit PCM (plain
 * signed sample values). Pure C (no HAL, no RTOS); the caller owns the
 * state, so nothing is allocated. No task of its own: only the Autotune
 * effect calls it (audio_effects.c), inside FxRenderTask while that task
 * makes an Autotune effect file. pitch_detector.c explains the method step
 * by step: decimation to 12 kHz, then normalised autocorrelation.
 */
#ifndef PITCH_DETECTOR_H
#define PITCH_DETECTOR_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

/*
 * The PITCH_DETECTOR_ settings below:
 * SAMPLE_RATE_HZ        the input rate it expects: 48 kHz
 * DECIMATION            every 4 input samples are averaged into one, so the
 *                       analysis runs at 48 kHz / 4 = 12 kHz
 *                       (PD_DECIMATED_RATE_HZ in pitch_detector.c)
 * BUFFER_SIZE           the analysis window: 512 samples at 12 kHz = 42.7 ms.
 *                       Even at the longest lag (150 samples, the 80 Hz
 *                       period) 362 samples, more than two periods, are
 *                       compared.
 * UPDATE_DECIMATED      a new estimate every 256 samples at 12 kHz = 21.3 ms,
 *                       so each window overlaps the one before by half
 */
#define PITCH_DETECTOR_SAMPLE_RATE_HZ         48000U
#define PITCH_DETECTOR_DECIMATION             4U
#define PITCH_DETECTOR_BUFFER_SIZE             512U
#define PITCH_DETECTOR_UPDATE_DECIMATED        256U

/** Persistent state for the decimated normalised-autocorrelation detector. */
typedef struct
{
    float buffer[PITCH_DETECTOR_BUFFER_SIZE];   /* the newest 512 decimated samples, circular, -1..1 */
    uint16_t write_index;                       /* next slot to write: also the oldest sample */
    uint16_t decimated_since_analysis;
    uint32_t total_decimated_samples;           /* counts up to 512 (the window is full), then stays */
    uint8_t decimation_count;                   /* input samples in the current group of 4 so far */
    float decimation_accumulator;               /* their sum */
    bool has_analysed;
    bool pitch_valid;
    float last_pitch_hz;
    float last_confidence;
} PitchDetector;

/**
 * @brief Initialise a pitch detector to an empty state.
 * @param detector Detector state. NULL is safely ignored.
 */
void PitchDetector_Init(PitchDetector *detector);

/**
 * @brief Clear all accumulated detector samples and previous results.
 * @param detector Detector state. NULL is safely ignored.
 */
void PitchDetector_Reset(PitchDetector *detector);

/**
 * @brief Add a block of 48 kHz mono PCM samples and return the latest pitch estimate.
 * @param detector Persistent detector state.
 * @param input Signed 16-bit mono PCM input.
 * @param sample_count Number of input samples; must be greater than zero.
 * @param pitch_hz Optional output for detected fundamental frequency.
 * @param confidence Optional output for normalised autocorrelation confidence.
 * @return true when a valid pitch is currently available, otherwise false.
 */
bool PitchDetector_ProcessBlock(PitchDetector *detector,
                                const int16_t *input,
                                size_t sample_count,
                                float *pitch_hz,
                                float *confidence);

/**
 * @brief How many input samples ago the newest estimate was made.
 *        Autotune uses it to know when a new estimate has just arrived and
 *        how far it is between two estimates (they come every 1024 input
 *        samples, each describing the pitch at the middle of its window,
 *        1024 samples before it was made).
 * @param detector Detector state.
 * @return 0..1023 in normal use (0 = made on the last sample given), or -1
 *         when there is no estimate yet (or detector is NULL).
 */
int32_t PitchDetector_SamplesSinceEstimate(const PitchDetector *detector);

#endif
